import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HousingLocationComponent } from '../housing-location/housing-location.component';
import { HousingLocation } from '../housing-location';
import { HousingService } from '../housing.service';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, HousingLocationComponent],
  template: `
    <section>
      <form>
        <input type="text" placeholder="filter by city" #filter>
        <button class="primary" type="button" (click)="filteredResults(filter.value)">Search</button>
      </form>
    <section class="results">
      <app-housing-location *ngFor="let item of filteredLocationList"></app-housing-location>
    </section>
  `,
  styleUrls: ['./home.component.css']
})
export class HomeComponent {

  housingLocationList: HousingLocation[] = [];
  housingService: HousingService = inject(HousingService);
  filteredLocationList: HousingLocation[] = [];

  constructor(){
    this.housingService.getAllHousingLocations().then((item: HousingLocation[]) => {
      this.housingLocationList = item;
      this.filteredLocationList = item;
    });
  }

filteredResults(text: string){
  if (!text) {
    this.filteredLocationList = this.housingLocationList;
  }

  this.filteredLocationList = this.housingLocationList.filter(
    item => item?.city.toLowerCase().includes(text.toLowerCase())
  );

}

}
